/**
 * Creates an auth middleware that verifies tokens via the auth service.
 * This is used by external services (links, analytics) that don't own user data.
 */
export function createAuthMiddleware(userServiceUrl = "http://localhost:3001") {
  return async (req, res, next) => {
    try {
      const token =
        req.cookies.accessToken ||
        req.headers.authorization?.replace("Bearer ", "");
      if (!token)
        return res
          .status(401)
          .json({ message: "Unauthorized - No token provided" });

      try {
        const { data } = await axios.get(`${userServiceUrl}/api/profile`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        req.user = data.result;
        next();
      } catch (err) {
        if (err.response?.status === 401) {
          res.clearCookie("accessToken", ACCESS_COOKIE_OPTIONS);
          return res.status(401).json({ message: "Invalid or expired token" });
        }
        console.error("User service error:", err.message);
        return res.status(503).json({ message: "User service unavailable" });
      }
    } catch (error) {
      console.error("Authentication error:", error);
      res.status(500).json({ message: "Internal server error" });
    }
  };
}

